import pytest

from scheduler import order_tasks


def test_dependencies_come_before_dependents():
    deps = {'build': ['compile'], 'compile': ['fetch'], 'fetch': []}
    order = order_tasks(deps)
    assert set(order) == {'build', 'compile', 'fetch'}
    assert order.index('fetch') < order.index('compile') < order.index('build')


def test_dependency_only_mentioned_as_a_value_is_included():
    deps = {'app': ['lib']}
    order = order_tasks(deps)
    assert set(order) == {'app', 'lib'}
    assert order.index('lib') < order.index('app')


def test_diamond_dependency():
    deps = {'d': ['b', 'c'], 'b': ['a'], 'c': ['a'], 'a': []}
    order = order_tasks(deps)
    assert order.index('a') < order.index('b')
    assert order.index('a') < order.index('c')
    assert order.index('b') < order.index('d')
    assert order.index('c') < order.index('d')


def test_cycle_raises():
    deps = {'a': ['b'], 'b': ['a']}
    with pytest.raises(ValueError):
        order_tasks(deps)

