def order_tasks(deps):
    all_tasks = set(deps.keys())
    for dependencies in deps.values():
        all_tasks.update(dependencies)

    visited = set()
    in_progress = set()
    order = []

    def visit(task):
        if task in visited:
            return
        if task in in_progress:
            raise ValueError(f'cycle detected involving {task!r}')
        in_progress.add(task)
        for dep in deps.get(task, []):
            visit(dep)
        in_progress.discard(task)
        visited.add(task)
        order.append(task)

    for task in sorted(all_tasks):
        visit(task)
    return order

