def order_tasks(deps):
    all_tasks = set(deps.keys())
    for dependencies in deps.values():
        all_tasks.update(dependencies)

    remaining = dict(deps)
    for task in all_tasks:
        remaining.setdefault(task, [])

    order = []
    done = set()
    progressed = True
    while remaining and progressed:
        progressed = False
        for task in sorted(remaining):
            if all(d in done for d in remaining[task]):
                order.append(task)
                done.add(task)
                del remaining[task]
                progressed = True
                break
    return order
